//! Transient failure classes: a pure decision about whether a unit failure is
//! worth retrying, and under which class name.
//!
//! The `why`/`detail` pair comes from the real producers: `collect` builds
//! `why` as `"{state}/{detail}"` from pool reconcile states, and `merge`
//! reports `fetch-failed`, `merge-conflict` and `proof-failed`.

/// Lockfiles whose conflicts are regenerated by a merge rather than resolved
/// by hand — a conflict limited to these is transient.
const LOCKFILES: &[&str] = &[
    "Cargo.lock",
    "package-lock.json",
    "pnpm-lock.yaml",
    "yarn.lock",
    "deno.lock",
    "flake.lock",
    "uv.lock",
    "poetry.lock",
    "composer.lock",
    "Gemfile.lock",
    "go.sum",
];

/// The marker `merge` writes in front of the conflicting file list.
const CONFLICT_MARKER: &str = "Conflicting files:";

/// Classify a unit failure. `Some(class)` means the failure is transient and
/// belongs to that class; `None` means it is a real failure.
#[must_use]
pub fn classify(why: &str, detail: &str) -> Option<&'static str> {
    if why.starts_with("lost/") || why.starts_with("error/") {
        return Some("host");
    }
    if why == "fetch-failed" {
        return Some("host");
    }
    if why == "proof-failed" && proof_timed_out(detail) {
        return Some("timeout");
    }
    if why == "merge-conflict" && lockfile_conflict(detail) {
        return Some("generated-conflict");
    }
    None
}

/// A proof that was killed rather than failed: the command's own timeout exit
/// codes, or the host's timeout marker appended to the output.
fn proof_timed_out(detail: &str) -> bool {
    detail.contains("(exit 124)")
        || detail.contains("(exit 137)")
        || detail.contains("[timeout after")
}

/// Whether every conflicting file is a lockfile. An empty list is a real
/// conflict we cannot explain, so it is not transient.
fn lockfile_conflict(detail: &str) -> bool {
    let Some((_, files)) = detail.split_once(CONFLICT_MARKER) else {
        return false;
    };
    let files: Vec<&str> = files
        .lines()
        .map(str::trim)
        .filter(|f| !f.is_empty())
        .collect();
    !files.is_empty() && files.iter().all(|file| is_lockfile(file))
}

/// A path's basename compared against the lockfile set.
fn is_lockfile(path: &str) -> bool {
    let base = path.rsplit('/').next().unwrap_or(path);
    LOCKFILES.contains(&base)
}
